SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='3d073154-66b0-597d-8191-2f2ed91ce74e'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('efe122de-790d-5b2d-b09a-86b9b94b5e8f','7976a34e-adab-58c1-8991-51c45a79384f')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='3d073154-66b0-597d-8191-2f2ed91ce74e'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='3d073154-66b0-597d-8191-2f2ed91ce74e'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('efe122de-790d-5b2d-b09a-86b9b94b5e8f','7976a34e-adab-58c1-8991-51c45a79384f')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='3d073154-66b0-597d-8191-2f2ed91ce74e'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
 JOIN platform.runtime_command_receipt q ON q.id='efe122de-790d-5b2d-b09a-86b9b94b5e8f' AND q.owner_module_id='customer_buyer_profile' AND q.operation='SH-004.v1'
  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-customer-03-missing-event' AND q.fingerprint='57c7707c89a6e9980f0046eed06baeceb1d365797b3f3d57857012cc4d513f3f'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"customer-03-missing-event","status":"ok","value":{"customerProfileId":"3d073154-66b0-597d-8191-2f2ed91ce74e","userId":"6612df6d-65ca-5944-b4bf-031a0b15b41d","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"efe122de-790d-5b2d-b09a-86b9b94b5e8f","semanticKey":"customer-controls-customer-03-missing-event","fingerprint":"57c7707c89a6e9980f0046eed06baeceb1d365797b3f3d57857012cc4d513f3f","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='374b5366-7110-5648-bdd4-b95588e5d569' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='096326df-b582-574b-bc42-76f31545454e' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"3d073154-66b0-597d-8191-2f2ed91ce74e"},"prior":null,"committed":{"id":"3d073154-66b0-597d-8191-2f2ed91ce74e","userId":"6612df6d-65ca-5944-b4bf-031a0b15b41d","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='3d073154-66b0-597d-8191-2f2ed91ce74e' AND c.user_id='6612df6d-65ca-5944-b4bf-031a0b15b41d' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
  AND q.mutation_transaction_id=c.mutation_transaction_id AND h.mutation_transaction_id=c.mutation_transaction_id AND e.mutation_transaction_id=c.mutation_transaction_id
  AND (SELECT count(*) FROM platform.runtime_outbox_message o WHERE o.command_receipt_id=q.id AND o.producer_owner=q.owner_module_id
   AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0 AND o.schema_version='1'
   AND o.causation_id=q.id::text AND o.correlation_id='customer-03-missing-event' AND o.mutation_transaction_id=c.mutation_transaction_id
   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='5fc802d2-bfc2-52c1-9def-419165c21b10' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"3d073154-66b0-597d-8191-2f2ed91ce74e","userId":"6612df6d-65ca-5944-b4bf-031a0b15b41d","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='2f0d7410-b6aa-5119-89f5-216917538770' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"6612df6d-65ca-5944-b4bf-031a0b15b41d","track":"customer","customerProfileId":"3d073154-66b0-597d-8191-2f2ed91ce74e","sourceCreationRevision":"0","sourceCreationReceipt":"efe122de-790d-5b2d-b09a-86b9b94b5e8f","semanticKey":"customer_buyer_profile/3d073154-66b0-597d-8191-2f2ed91ce74e/default-free-enrollment/v1"}'::jsonb)))=2));
